Here's a simple recursive function to calculate the nth Fibonacci number:

```python
def fibonacci(n):
    if n <= 0:
        return "Input should be positive integer."
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)
```

However, this recursive approach is inefficient for large values of n because it performs a lot of repeated calculations. 

Here's a more efficient iterative approach:

```python
def fibonacci(n):
    if n <= 0:
        return "Input should be positive integer."
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        fib_prev = 0
        fib_curr = 1
        for i in range(2, n):
            fib_next = fib_prev + fib_curr
            fib_prev = fib_curr
            fib_curr = fib_next
        return fib_curr
```

And here's a version using memoization to store previously calculated values:

```python
def fibonacci(n, memo = {}):
    if n <= 0:
        return "Input should be positive integer."
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    elif n in memo:
        return memo[n]
    else:
        result = fibonacci(n-1, memo) + fibonacci(n-2, memo)
        memo[n] = result
        return result
```

The last version is the most efficient for large values of n.

Te explico **reentrancy** — es la vulnerabilidad más famosa de Solidity (fue la causa del hack de The DAO en 2016, $60M perdidos).

## ¿Qué es?

Un ataque donde un contrato malicioso **vuelve a llamar** a tu contrato antes de que termine de actualizar su estado interno. El atacante "re-entra" en la función mientras el estado todavía está inconsistente.

## Ejemplo vulnerable

```solidity
// ❌ VULNERABLE
contract BilleteraSimple {
    mapping(address => uint256) public balances;

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function withdraw() external {
        uint256 amount = balances[msg.sender];
        require(amount > 0, "No tenes fondos");

        // ⚠️ Envía ETH ANTES de actualizar el balance
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "Transferencia fallida");

        // ⚠️ Actualiza el balance DESPUÉS — demasiado tarde
        balances[msg.sender] = 0;
    }
}
```

## ¿Cómo lo explota un atacante?

```solidity
contract Atacante {
    BilleteraVulnerable public victima;

    constructor(address _victima) {
        victima = BilleteraVulnerable(_victima);
    }

    function atacar() external payable {
        victima.deposit{value: 1 ether}();
        victima.withdraw();
    }

    // ⚡ Esta función se dispara cuando recibe ETH
    receive() external payable {
        if (address(victima).balance >= 1 ether) {
            victima.withdraw(); // ¡Re-entra!
        }
    }
}
```

**Flujo del ataque:**
1. Atacante deposita 1 ETH
2. Atacante llama `withdraw()`
3. Contrato envía 1 ETH → dispara `receive()` del atacante
4. `receive()` llama `withdraw()` otra vez — **el balance todavía dice 1 ETH** porque no se actualizó
5. El ciclo se repite hasta vaciar el contrato

## Solución correcta

```solidity
// ✅ SEGURO
contract BilleteraSegura {
    mapping(address => uint256) public balances;

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function withdraw() external {
        uint256 amount = balances[msg.sender];
        require(amount > 0, "No tenés fondos");

        // ✅ Actualizamos el estado ANTES de transferir
        balances[msg.sender] = 0;

        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "Transferencia fallida");
    }
}
```

**Regla de oro:** siempre actualizá el estado interno **antes** de hacer llamadas externas (`call`, `transfer`, `send`). Si el atacante intenta re-entrar, el balance ya es `0` y el `require` lo frena.

